import { DOCUMENT, isPlatformBrowser, NgTemplateOutlet } from "@angular/common";
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  DestroyRef,
  Directive,
  inject,
  Injector,
  input,
  type OnInit,
  PLATFORM_ID,
  runInInjectionContext,
  signal,
  TemplateRef,
  type WritableSignal,
} from "@angular/core";
import { toSignal } from "@angular/core/rxjs-interop";
import { NavigationEnd, Router, RouterLink } from "@angular/router";
import { NgIcon } from "@ng-icons/core";
import { lucideMenu, lucidePanelLeft, lucidePanelLeftClose, lucideSearch } from "@ng-icons/lucide";
import { filter, map } from "rxjs";
import { isMacPlatform, isPaletteShortcut, shortcutLabel, urlPath } from "@/ui/layout/app-shell";
import { KoCommandPalette } from "@/ui/layout/command-palette.component";
import { KoCommandRegistry } from "@/ui/layout/command-registry";
import { isNavActive, type NavConfig } from "@/ui/layout/nav";
import { persisted } from "@/ui/persisted";
import { KoIconButton } from "@/ui/primitives/button.component";
import {
  KoSheet,
  KoSheetContent,
  KoSheetDescription,
  KoSheetTitle,
} from "@/ui/primitives/sheet.component";
import { KoTooltip } from "@/ui/primitives/tooltip.directive";
import { cn } from "@/ui/utils";

export type Brand = {
  name: string;
  /** A second line under the name, such as the product area. */
  tagline?: string;
  /** The SVG string of the icon, such as `lucideBoxes` from `@ng-icons/lucide`. */
  icon: string;
};

/** The context of `koSidebarFooter`: `let-collapsed` is whether the sidebar is collapsed. */
export type KoSidebarFooterContext = { $implicit: boolean };

/** The foot of the sidebar: `<ng-template koSidebarFooter let-collapsed>`. */
@Directive({ selector: "ng-template[koSidebarFooter]" })
export class KoSidebarFooter {
  readonly template = inject<TemplateRef<KoSidebarFooterContext>>(TemplateRef);

  static ngTemplateContextGuard(
    _directive: KoSidebarFooter,
    _context: unknown,
  ): _context is KoSidebarFooterContext {
    return true;
  }
}

const linkClass =
  "flex h-9 items-center gap-2.5 rounded-md px-2.5 text-sm font-medium text-muted-foreground transition-[background-color,color] duration-150 hover:bg-secondary hover:text-foreground";

/**
 * The frame of every page: the sidebar (collapsible on desktop, a sheet on mobile), the header
 * with the command palette (Ctrl+K, or ⌘K on macOS), and the page, projected into `<main>`,
 * which is the scroll container. `[koHeaderEnd]` content goes at the right of the header.
 */
@Component({
  selector: "ko-app-shell",
  imports: [
    NgTemplateOutlet,
    NgIcon,
    RouterLink,
    KoIconButton,
    KoTooltip,
    KoSheet,
    KoSheetContent,
    KoSheetTitle,
    KoSheetDescription,
    KoCommandPalette,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "flex h-dvh overflow-hidden bg-background text-foreground" },
  templateUrl: "./app-shell.component.html",
})
export class KoAppShell implements OnInit {
  readonly nav = input.required<NavConfig>();
  readonly brand = input.required<Brand>();
  /** Pages that scroll their own panes get a fixed-height `<main>` instead of a scrolling one. */
  readonly fullHeight = input<(path: string) => boolean>();
  /** The localStorage key prefix; the collapsed state is kept at `{storageKey}:collapsed`. Read once. */
  readonly storageKey = input("app-shell");

  protected readonly menuIcon = lucideMenu;
  protected readonly expandIcon = lucidePanelLeft;
  protected readonly collapseIcon = lucidePanelLeftClose;
  protected readonly searchIcon = lucideSearch;

  protected readonly footer = contentChild(KoSidebarFooter);
  protected readonly menu = signal(false);
  protected readonly palette = signal(false);
  /** Replaced in `ngOnInit`, once `storageKey` is known. */
  protected collapsed: WritableSignal<boolean> = signal(false);
  protected readonly commands = inject(KoCommandRegistry).commands;

  private readonly router = inject(Router);
  private readonly injector = inject(Injector);
  private readonly browser = isPlatformBrowser(inject(PLATFORM_ID));
  private readonly mac = this.browser && isMacPlatform(navigator);

  protected readonly shortcut = shortcutLabel(this.mac);
  protected readonly path = toSignal(
    this.router.events.pipe(
      filter((event) => event instanceof NavigationEnd),
      map(() => urlPath(this.router.url)),
    ),
    { initialValue: urlPath(this.router.url) },
  );
  protected readonly asideClasses = computed(() =>
    cn(
      "hidden shrink-0 border-r border-border transition-[width] duration-200 ease-[var(--ease-smooth-out)] lg:flex",
      this.collapsed() ? "w-16" : "w-52",
    ),
  );
  protected readonly mainClasses = computed(() =>
    cn(
      "min-h-0 min-w-0 flex-1",
      this.fullHeight()?.(this.path()) ? "flex flex-col overflow-hidden" : "overflow-y-auto",
    ),
  );

  constructor() {
    if (!this.browser) return;
    const document = inject(DOCUMENT);
    const onKey = (event: KeyboardEvent) => {
      if (!isPaletteShortcut(event, this.mac)) return;
      event.preventDefault();
      this.palette.update((open) => !open);
    };
    document.addEventListener("keydown", onKey);
    inject(DestroyRef).onDestroy(() => document.removeEventListener("keydown", onKey));
  }

  ngOnInit(): void {
    const key = `${this.storageKey()}:collapsed`;
    this.collapsed = runInInjectionContext(this.injector, () => persisted(key, false));
  }

  protected isActive(to: string): boolean {
    return isNavActive(this.path(), to);
  }

  protected linkClasses(active: boolean, collapsed: boolean): string {
    return cn(
      linkClass,
      active && "bg-secondary text-foreground",
      collapsed && "justify-center px-0",
    );
  }

  protected toggleCollapsed(): void {
    this.collapsed.update((collapsed) => !collapsed);
  }

  /** Closes the mobile sheet after a link in it is followed. */
  protected navigated(mobile: boolean): void {
    if (mobile) this.menu.set(false);
  }
}

type ShortcutEvent = Pick<KeyboardEvent, "key" | "ctrlKey" | "metaKey" | "altKey" | "isComposing">;

/** Ctrl+K, or ⌘K on macOS; never while an IME is composing. */
export function isPaletteShortcut(event: ShortcutEvent, mac: boolean): boolean {
  if (event.isComposing || event.altKey || event.key.toLowerCase() !== "k") return false;
  return mac ? event.metaKey && !event.ctrlKey : event.ctrlKey && !event.metaKey;
}

type PlatformInfo = { platform?: string; userAgentData?: { platform?: string } };

/** macOS and iOS, from `navigator.userAgentData` where the browser has it. */
export function isMacPlatform(navigator: PlatformInfo): boolean {
  const platform = navigator.userAgentData?.platform ?? navigator.platform ?? "";
  return /mac|iphone|ipad|ipod/i.test(platform);
}

/** The hint on the header's search button. */
export function shortcutLabel(mac: boolean): string {
  return mac ? "⌘K" : "Ctrl K";
}

/** The path of a router URL, without the query and the fragment. */
export function urlPath(url: string): string {
  return url.split(/[?#]/)[0] || "/";
}

import { describe, expect, it } from "vitest";
import { isMacPlatform, isPaletteShortcut, shortcutLabel, urlPath } from "./app-shell";

const key = (init: Partial<KeyboardEvent>) =>
  ({
    key: "k",
    ctrlKey: false,
    metaKey: false,
    altKey: false,
    isComposing: false,
    ...init,
  }) as Pick<KeyboardEvent, "key" | "ctrlKey" | "metaKey" | "altKey" | "isComposing">;

describe("isPaletteShortcut", () => {
  it("is Ctrl+K off macOS", () => {
    expect(isPaletteShortcut(key({ ctrlKey: true }), false)).toBe(true);
    expect(isPaletteShortcut(key({ key: "K", ctrlKey: true }), false)).toBe(true);
    expect(isPaletteShortcut(key({ metaKey: true }), false)).toBe(false);
  });

  it("is Cmd+K on macOS", () => {
    expect(isPaletteShortcut(key({ metaKey: true }), true)).toBe(true);
    expect(isPaletteShortcut(key({ ctrlKey: true }), true)).toBe(false);
  });

  it("ignores other keys, Alt, and IME composition", () => {
    expect(isPaletteShortcut(key({ key: "j", ctrlKey: true }), false)).toBe(false);
    expect(isPaletteShortcut(key({}), false)).toBe(false);
    expect(isPaletteShortcut(key({ ctrlKey: true, altKey: true }), false)).toBe(false);
    expect(isPaletteShortcut(key({ ctrlKey: true, isComposing: true }), false)).toBe(false);
  });
});

describe("isMacPlatform", () => {
  it("reads userAgentData first, then navigator.platform", () => {
    expect(isMacPlatform({ userAgentData: { platform: "macOS" }, platform: "Win32" })).toBe(true);
    expect(isMacPlatform({ platform: "MacIntel" })).toBe(true);
    expect(isMacPlatform({ platform: "iPhone" })).toBe(true);
    expect(isMacPlatform({ platform: "Win32" })).toBe(false);
    expect(isMacPlatform({ userAgentData: { platform: "Windows" }, platform: "MacIntel" })).toBe(
      false,
    );
    expect(isMacPlatform({})).toBe(false);
  });
});

describe("shortcutLabel", () => {
  it("is Ctrl K off macOS and ⌘K on it", () => {
    expect(shortcutLabel(false)).toBe("Ctrl K");
    expect(shortcutLabel(true)).toBe("⌘K");
  });
});

describe("urlPath", () => {
  it("drops the query and the fragment", () => {
    expect(urlPath("/grid?sort=name#top")).toBe("/grid");
    expect(urlPath("/detail/itm-01#notes")).toBe("/detail/itm-01");
    expect(urlPath("/")).toBe("/");
    expect(urlPath("")).toBe("/");
  });
});

import {
  ChangeDetectionStrategy,
  Component,
  provideZonelessChangeDetection,
  signal,
} from "@angular/core";
import { TestBed, type ComponentFixture } from "@angular/core/testing";
import { provideRouter, Router, RouterOutlet } from "@angular/router";
import { lucideBoxes, lucideHouse, lucideSettings, lucideTable2 } from "@ng-icons/lucide";
import { KoAppShell, KoSidebarFooter, type Brand } from "@/ui/layout/app-shell.component";
import { KoCommandPalette } from "@/ui/layout/command-palette.component";
import { injectCommands, KoCommandRegistry, type Command } from "@/ui/layout/command-registry";
import type { NavConfig } from "@/ui/layout/nav";

const nav: NavConfig = {
  primary: [
    { to: "/", label: "Overview", icon: lucideHouse, keywords: ["home"] },
    { to: "/grid", label: "Data grid", icon: lucideTable2 },
  ],
  secondary: [
    { to: "/settings", label: "Settings", icon: lucideSettings, keywords: ["preferences"] },
  ],
};
const brand: Brand = { name: "Shared UI", tagline: "Showcase", icon: lucideBoxes };

@Component({
  selector: "ko-blank-page",
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<p id="page">Page</p>`,
})
class BlankPage {}

const routes = [
  { path: "", component: BlankPage },
  { path: "grid", component: BlankPage },
  { path: "settings", component: BlankPage },
];

const el = (selector: string) => document.querySelector<HTMLElement>(selector);
const all = (selector: string) => Array.from(document.querySelectorAll<HTMLElement>(selector));
const press = (target: Element, key: string, init: KeyboardEventInit = {}) =>
  target.dispatchEvent(
    new KeyboardEvent("keydown", {
      key,
      keyCode: key === "Escape" ? 27 : 0,
      bubbles: true,
      cancelable: true,
      ...init,
    }),
  );
const type = (input: HTMLInputElement, value: string) => {
  input.value = value;
  input.dispatchEvent(new Event("input", { bubbles: true }));
};
const optionLabels = () =>
  all('[role="option"]').map((option) => option.querySelector("span")!.textContent!.trim());

async function settle(fixture: ComponentFixture<unknown>) {
  for (let i = 0; i < 2; i++) {
    fixture.detectChanges();
    await fixture.whenStable();
    await new Promise((resolve) => setTimeout(resolve, 0));
  }
  fixture.detectChanges();
}

/** Waits out the exit animation's timeout fallback (jsdom fires no `animationend`). */
async function exited(fixture: ComponentFixture<unknown>) {
  await new Promise((resolve) => setTimeout(resolve, 400));
  await settle(fixture);
}

function clearOverlays() {
  document.querySelectorAll(".cdk-overlay-container").forEach((node) => node.replaceChildren());
}

describe("KoCommandPalette", () => {
  @Component({
    selector: "ko-palette-host",
    imports: [KoCommandPalette],
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<ko-command-palette [(open)]="open" [nav]="nav" [commands]="commands" />`,
  })
  class PaletteHost {
    readonly open = signal(false);
    readonly nav = nav;
    readonly ran = signal<string[]>([]);
    readonly commands: Command[] = [
      {
        id: "new",
        label: "New item",
        group: "Actions",
        run: () => this.ran.update((list) => [...list, "new"]),
      },
      {
        id: "reset",
        label: "Reset settings",
        group: "Actions",
        run: () => this.ran.update((list) => [...list, "reset"]),
      },
      {
        id: "theme",
        label: "Toggle theme",
        group: "Appearance",
        keywords: ["settings", "dark"],
        run: () => this.ran.update((list) => [...list, "theme"]),
      },
    ];
  }

  let fixture: ComponentFixture<PaletteHost>;
  let host: PaletteHost;
  const input = () => el('input[role="combobox"]') as HTMLInputElement;
  const headings = () =>
    all('[role="group"]').map((group) =>
      document.getElementById(group.getAttribute("aria-labelledby")!)!.textContent!.trim(),
    );

  beforeEach(async () => {
    TestBed.configureTestingModule({
      providers: [provideZonelessChangeDetection(), provideRouter(routes)],
    });
    fixture = TestBed.createComponent(PaletteHost);
    host = fixture.componentInstance;
    document.body.appendChild(fixture.nativeElement);
    host.open.set(true);
    await settle(fixture);
  });

  afterEach(() => {
    fixture.destroy();
    clearOverlays();
  });

  it("lists commands by group, then the pages, in a labelled combobox and listbox", () => {
    expect(optionLabels()).toEqual([
      "New item",
      "Reset settings",
      "Toggle theme",
      "Overview",
      "Data grid",
      "Settings",
    ]);
    expect(headings()).toEqual(["Actions", "Appearance", "Pages"]);
    const listbox = el('[role="listbox"]')!;
    expect(input().getAttribute("aria-controls")).toBe(listbox.id);
    expect(input().getAttribute("aria-expanded")).toBe("true");
    expect(input().getAttribute("aria-activedescendant")).toBe(all('[role="option"]')[0].id);
    expect(input().placeholder).toBe("Search…");
    expect(el('[role="dialog"]')!.getAttribute("aria-labelledby")).toBeTruthy();
  });

  it("filters on 'sett' and runs the second match on ArrowDown then Enter", async () => {
    type(input(), "sett");
    await settle(fixture);
    expect(optionLabels()).toEqual(["Reset settings", "Toggle theme", "Settings"]);
    expect(headings()).toEqual(["Actions", "Appearance", "Navigate"]);

    press(input(), "ArrowDown");
    await settle(fixture);
    const options = all('[role="option"]');
    expect(options[1].getAttribute("aria-selected")).toBe("true");
    expect(input().getAttribute("aria-activedescendant")).toBe(options[1].id);

    press(input(), "Enter");
    await settle(fixture);
    expect(host.ran()).toEqual(["theme"]);
    await exited(fixture);
    expect(host.open()).toBe(false);
    expect(el('[role="dialog"]')).toBeNull();
  });

  it("navigates for a page, and wraps around from the first option with ArrowUp", async () => {
    const router = TestBed.inject(Router);
    type(input(), "sett");
    await settle(fixture);
    press(input(), "ArrowUp");
    await settle(fixture);
    press(input(), "Enter");
    await settle(fixture);
    expect(router.url).toBe("/settings");
    expect(host.ran()).toEqual([]);
    await exited(fixture);
    expect(host.open()).toBe(false);
  });

  it("shows the empty message when nothing matches", async () => {
    type(input(), "zzz");
    await settle(fixture);
    expect(all('[role="option"]')).toEqual([]);
    expect(el('[role="listbox"]')!.textContent).toContain("Nothing matches.");
    expect(input().hasAttribute("aria-activedescendant")).toBe(false);
  });

  it("closes on Escape and clears the query", async () => {
    type(input(), "sett");
    await settle(fixture);
    press(input(), "Escape");
    await settle(fixture);
    await exited(fixture);
    expect(host.open()).toBe(false);
    expect(el('[role="dialog"]')).toBeNull();
    host.open.set(true);
    await settle(fixture);
    expect(input().value).toBe("");
    expect(all('[role="option"]').length).toBe(6);
  });

  it("runs an option on click", async () => {
    all('[role="option"]')[0].click();
    await settle(fixture);
    expect(host.ran()).toEqual(["new"]);
    await exited(fixture);
    expect(host.open()).toBe(false);
  });
});

describe("KoCommandRegistry and injectCommands", () => {
  @Component({
    selector: "ko-commands-owner",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: ``,
  })
  class CommandsOwner {
    constructor() {
      injectCommands([{ id: "a", label: "A", group: "G", run: () => undefined }]);
    }
  }

  @Component({
    selector: "ko-signal-commands-owner",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: ``,
  })
  class SignalCommandsOwner {
    readonly list = signal<Command[]>([{ id: "b", label: "B", group: "G", run: () => undefined }]);
    constructor() {
      injectCommands(this.list);
    }
  }

  beforeEach(() => {
    TestBed.configureTestingModule({ providers: [provideZonelessChangeDetection()] });
  });

  it("adds a component's commands while it lives, and removes them when destroyed", () => {
    const registry = TestBed.inject(KoCommandRegistry);
    expect(registry.commands()).toEqual([]);
    const owner = TestBed.createComponent(CommandsOwner);
    expect(registry.commands().map((command) => command.id)).toEqual(["a"]);
    owner.destroy();
    expect(registry.commands()).toEqual([]);
  });

  it("follows a signal of commands", async () => {
    const registry = TestBed.inject(KoCommandRegistry);
    const owner = TestBed.createComponent(SignalCommandsOwner);
    await owner.whenStable();
    expect(registry.commands().map((command) => command.id)).toEqual(["b"]);
    owner.componentInstance.list.set([
      { id: "c", label: "C", group: "G", run: () => undefined },
      { id: "d", label: "D", group: "G", run: () => undefined },
    ]);
    await owner.whenStable();
    expect(registry.commands().map((command) => command.id)).toEqual(["c", "d"]);
    owner.destroy();
    expect(registry.commands()).toEqual([]);
  });

  it("register replaces an owner's commands, unregister removes them", () => {
    const registry = TestBed.inject(KoCommandRegistry);
    const run = () => undefined;
    registry.register("x", [{ id: "1", label: "1", group: "G", run }]);
    registry.register("y", [{ id: "2", label: "2", group: "G", run }]);
    registry.register("x", [{ id: "3", label: "3", group: "G", run }]);
    expect(registry.commands().map((command) => command.id)).toEqual(["3", "2"]);
    registry.unregister("x");
    expect(registry.commands().map((command) => command.id)).toEqual(["2"]);
  });
});

describe("KoAppShell", () => {
  @Component({
    selector: "ko-shell-host",
    imports: [KoAppShell, KoSidebarFooter, RouterOutlet],
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `
      <ko-app-shell [nav]="nav" [brand]="brand" storageKey="shell-spec" [fullHeight]="fullHeight">
        <button koHeaderEnd id="header-end" type="button">Account</button>
        <ng-template koSidebarFooter let-collapsed>
          <span id="footer">{{ collapsed ? "short" : "long" }}</span>
        </ng-template>
        <router-outlet />
      </ko-app-shell>
    `,
  })
  class ShellHost {
    readonly nav = nav;
    readonly brand = brand;
    readonly fullHeight = (path: string) => path.startsWith("/grid");
  }

  let fixture: ComponentFixture<ShellHost>;

  async function create() {
    fixture = TestBed.createComponent(ShellHost);
    document.body.appendChild(fixture.nativeElement);
    await settle(fixture);
  }

  beforeEach(async () => {
    localStorage.clear();
    TestBed.configureTestingModule({
      providers: [provideZonelessChangeDetection(), provideRouter(routes)],
    });
    await TestBed.inject(Router).navigateByUrl("/settings");
    await create();
  });

  afterEach(() => {
    fixture.destroy();
    clearOverlays();
    localStorage.clear();
  });

  const desktopLinks = () => all("aside nav a");
  const toggle = () =>
    all("header button").find((button) =>
      /(Collapse|Expand) navigation/.test(button.getAttribute("aria-label") ?? ""),
    )!;

  it("projects the page, the header end and the sidebar footer", () => {
    expect(el("main #page")).not.toBeNull();
    expect(el("header #header-end")).not.toBeNull();
    expect(el("aside #footer")!.textContent).toBe("long");
    expect(el("aside")!.textContent).toContain("Shared UI");
    expect(el("aside")!.textContent).toContain("Showcase");
  });

  it("marks the nav item of the current route with aria-current", async () => {
    const current = () =>
      desktopLinks()
        .filter((link) => link.getAttribute("aria-current") === "page")
        .map((link) => link.getAttribute("href"));
    expect(current()).toEqual(["/settings"]);
    await TestBed.inject(Router).navigateByUrl("/grid?sort=name");
    await settle(fixture);
    expect(current()).toEqual(["/grid"]);
  });

  it("makes main the scroll container, or a fixed-height column for fullHeight pages", async () => {
    expect(el("main")!.className).toContain("overflow-y-auto");
    await TestBed.inject(Router).navigateByUrl("/grid");
    await settle(fixture);
    expect(el("main")!.className).toContain("overflow-hidden");
    expect(el("main")!.className).not.toContain("overflow-y-auto");
  });

  it("opens the palette with Ctrl+K, and closes it with Ctrl+K again", async () => {
    expect(el('[role="dialog"]')).toBeNull();
    press(document.body, "k", { ctrlKey: true });
    await settle(fixture);
    expect(el('input[role="combobox"]')).not.toBeNull();
    press(document.body, "k", { ctrlKey: true });
    await exited(fixture);
    expect(el('input[role="combobox"]')).toBeNull();
  });

  it("ignores Ctrl+K while an IME is composing", async () => {
    press(document.body, "k", { ctrlKey: true, isComposing: true });
    await settle(fixture);
    expect(el('[role="dialog"]')).toBeNull();
  });

  it("lists commands registered with injectCommands in the palette", async () => {
    TestBed.inject(KoCommandRegistry).register("spec", [
      { id: "x", label: "Sign out", group: "Account", run: () => undefined },
    ]);
    press(document.body, "k", { ctrlKey: true });
    await settle(fixture);
    expect(optionLabels()).toContain("Sign out");
    TestBed.inject(KoCommandRegistry).unregister("spec");
  });

  it("collapses the sidebar, with tooltips and labels on the links, and persists it", async () => {
    expect(toggle().getAttribute("aria-label")).toBe("Collapse navigation");
    toggle().click();
    await settle(fixture);
    expect(toggle().getAttribute("aria-label")).toBe("Expand navigation");
    expect(el("aside")!.className).toContain("w-16");
    expect(el("aside #footer")!.textContent).toBe("short");
    expect(desktopLinks()[0].getAttribute("aria-label")).toBe("Overview");
    expect(localStorage.getItem("shell-spec:collapsed")).toBe("true");

    fixture.destroy();
    await create();
    expect(toggle().getAttribute("aria-label")).toBe("Expand navigation");
    expect(el("aside")!.className).toContain("w-16");
  });

  it("opens the mobile nav in a sheet and closes it on navigation", async () => {
    const open = all("header button").find(
      (button) => button.getAttribute("aria-label") === "Open navigation",
    )!;
    open.click();
    await settle(fixture);
    const sheet = el('[role="dialog"]')!;
    expect(sheet.textContent).toContain("Navigation");
    const link = Array.from(sheet.querySelectorAll<HTMLElement>("nav a")).find(
      (a) => a.getAttribute("href") === "/grid",
    )!;
    link.click();
    await settle(fixture);
    await exited(fixture);
    expect(el('[role="dialog"]')).toBeNull();
    expect(TestBed.inject(Router).url).toBe("/grid");
  });
});
